from adjudication_io import E, read_rows, write_adjudication
import json
r=json.loads((E/'reader_reports/145_scan006_reviewed.json').read_text())
first={x['box']:x['reading'] for x in read_rows(E/'second/145_scan006_first.tsv')}
boxes={x['box']:[int(x[k]) for k in ['x0','y0','x1','y1']] for x in read_rows(E/'second/145_scan006_boxes.tsv')}
oldfactor=r'\deleted{\unsure{l_1}}';newfactor=r'\deleted{\unsure{l_1|l_1^2|l_0^2}}'
oldpi=r'\unsure{\pi_{0,3}|\Pi_{0,3}}';newpi=r'\Pi_{0,3}'
oldmark=r'\unsure{2|z|t}';newmark=r'\unsure{2|z|t|\tau}'
oldparen=r'\sigma_0(l_0)^{-1}';newparen=r'\sigma_0\unsure{(}l_0)^{-1}'
qual=r'du moins \unsure{pas sur|pour|par sur}'
choices={
'B01':{'use_first':True,'adjudication':'Retain pas de and the unresolved ornate-S alphabet.','ink':'The first word ends in a downward rounded s trace, rather than the upward shoulder of r. The d has a rising loop and a low e continuation; no independent additional s is plain. The ornate sign and lower3 are unchanged.'},
'B02':{'use_first':True,'adjudication':'Retain the full cancelled formula, with its unresolved middle inverse product, and live dans. The dollar/display wrappers differ only in serialization.','ink':'The two bracketed sigma roofs and their indices survive; after the closing bracket there are further sigma-like roofs and raised inverse traces before the equals. They cannot be omitted, but hatching prevents resolving the existing uncertainty. The right-hand d is followed by the compressed a/n/s continuation. The upper equation is separate live replacement ink.'},
'B03':{'use_first':True,'adjudication':'Retain lowercase pi and the struck sigma product.','ink':'The pi has a curved returning right foot at the local x-height. The cancelled fragment has two sigma roofs, a round lower0 and the descending lower1; it is not the three prose letters car.'},
'B04':{'final':first['B04'].replace(oldfactor,newfactor).replace(oldparen,newparen),'changed':True,'adjudication':'Retain the calculation, add local doubt to the crowded opening parenthesis, and broaden the still-cancelled final-factor alternatives. The isolated right mark is adjudicated separately in B14.','ink':'The second sigma0-to-l0 junction has a faint curve crowded against the l loop; the opening parenthesis is plausible but not independently plain. The cancelled terminal l retains a dark lower index and an upper hooked trace that may be a2 or part of the hatching. Retain l1 first, while allowing l1 squared and l0 squared. All other displayed factors and signs agree; aligned/display wrappers do not alter the reading.'},
'B05':{'use_first':True,'adjudication':'Retain lowercase pi and et de barred-m.','ink':'The group sign again has a curved right foot. The small word after et has a round d body with its short rising return, followed by a low e; the initial body is not an independent o followed by n. The next sign has a separate overbar and curved m body.'},
'B06':{'use_first':True,'adjudication':'Retain lower index0 in the second conjugating loop.','ink':'The upper l-infinity has two identifiable lower components. In the lower row the l foot enters one rounded lower0 with a returning tail; it lacks the two-lobed infinity outline. Both inverse exponents and the rho factors are present. Display wrappers are equivalent.'},
'B08':{'final':'('+qual,'changed':True,'adjudication':'Broaden and reorder the qualification after du moins: pas sur is now preferred, with pour and par sur retained as alternatives.','ink':'After the clear du moins, a p stem and pale low strokes are followed by a separated dark s-like rise and a u/r continuation. The second reading exposes a two-word possibility that the first compressed to pour. The pale middle letters do not justify choosing pas against par absolutely or excluding the earlier one-word reading.'},
'B09':{'use_first':True,'adjudication':'Retain the final Le.','ink':'The terminal capital L joins a low open e hook, without the closed a body and return stroke proposed by La. The preceding group, set difference, punctures and fixed-point wording agree.'},
'B10':{'use_first':True,'adjudication':'Retain Z/3Z, the inserted pi/Pi doubt and the provient/pvt contraction doubt.','ink':'The denominator has the curved3, followed by a distinct second Z. The inserted group sign is heavily retraced and does not securely settle pi case; a Gamma interpretation is not established by an independently short right return. The lower word has a p descender, compressed internal joins and final t, followed by a d-rise and u, not a separate être.'},
'B11':{'use_first':True,'adjudication':'Retain deux!, inserted savoir, the uncertain fixed-point expression, qu’on and the cancelled/live wording with its existing doubts. Retain pi subscript1 without a final stop.','ink':'The short word before the exclamation has a d and a low crossed x ending. The insertion contains the low s/a/v joins and a dotted i before r. The left sign and bar above j remain uncertain. The baseline q has a long descender, and the cancelled word keeps a p stem but obscured internal letters. The tiny following live trace remains uncertain a. The last small curved pi has a separate lower1, not a comma.'},
'B12':{'final':first['B12'].replace(oldpi,newpi),'changed':True,'adjudication':'Retain aussi qu’on écrira and resolve the inserted group sign as capital Pi.','ink':'Aussi has the small doubled-s joins and final dotted i; qu’on has the q descender and separated apostrophe. Écrira has a c curve and short r/i strokes, without the tall letters of celui-ci or the stop sequence of c’est. The inserted Pi has a full cap and two long distinct legs; the neighboring Gamma has only a short right return. The large curve after Teichmüller is an insertion guide.'},
'B14':{'final':first['B14'].replace(oldmark,newmark),'changed':True,'adjudication':'Keep the isolated mark in the margin and add tau to its alternatives.','ink':'A dark upper hooked/crossed cap descends diagonally to a lower rightward foot. It remains compatible with2 or a letter-like trace; tau is a reasonable additional reading, not a resolution. Its placement away from the equation is preserved.'}}
edits=[{'old':oldfactor,'new':newfactor},{'old':oldparen,'new':newparen},{'old':'du moins pour','new':qual},{'old':oldpi,'new':newpi},{'old':oldmark,'new':newmark}]
for c in r['changes']:
 if c['id']=='s006-05':
  c.update(C='du moins pour',H=r'en \uncertain{restant} pour',final=qual,ink=choices['B08']['ink'],confidence='medium',c_changed=True,crop='crops/second_145_scan006_B08.png',box=boxes['B08'])
 if c['id']=='s006-12':
  c['final']=c['final'].replace(oldpi,newpi);c['ink']=choices['B12']['ink'];c['c_changed']=True;c['crop']='crops/second_145_scan006_B12.png';c['box']=boxes['B12']
 if c['id']=='s006-16':
  c['final']=c['final'].replace(oldmark,newmark);c['ink']=choices['B14']['ink'];c['crop']='crops/second_145_scan006_B14.png';c['box']=boxes['B14']
r['doubts']=[d for d in r['doubts'] if d['reading']!=oldpi]
for d in r['doubts']:
 if oldfactor in d['reading']:d.update(reading=d['reading'].replace(oldfactor,newfactor),alternatives=[r'l_1',r'l_1^2',r'l_0^2','overwritten lower index'],reason=choices['B04']['ink'])
 if oldmark in d['reading']:d.update(reading=d['reading'].replace(oldmark,newmark),alternatives=['2','z','t',r'\tau','nonsemantic pen mark'],reason=choices['B14']['ink'])
r['doubts'].extend([{'place':'Qualification after du moins','reading':r'\unsure{pas sur|pour|par sur}','alternatives':['pas sur','pour','par sur'],'confidence':'medium','reason':choices['B08']['ink']},{'place':'Second calculation, sigma0 argument opening','reading':r'\sigma_0\unsure{(}l_0)^{-1}','alternatives':['opening parenthesis','no independently separate opening parenthesis'],'confidence':'low','reason':'The left curve is crowded into the tall l loop; the second reading led to retaining a local presence doubt.'}])
for d in r['unlisted_decisions']:
 if d['id']=='U006-03':d.update(reading=newfactor,ink=choices['B04']['ink'],crop='crops/second_145_scan006_B04.png',box=boxes['B04'])
for i in r['inventory']:
 if i['element']=='M01':i['first_words_or_objects']='uncertain isolated 2/z/t/tau-like mark'
r['notes']=[n.replace('“du moins pour le groupe discret”','“du moins [pas sur / pour / par sur] le groupe discret”, with the compressed qualification now explicitly uncertain').replace('an interlinear Gamma_0,3 acting on a pi/Pi group with subscript 0,3','an interlinear Gamma_0,3 acting on a capital-Pi group with subscript0,3').replace('isolated 2/z/t-like mark','isolated 2/z/t/tau-like mark').replace('and the case of the two inserted pi forms','and initially the case of the two inserted pi forms (the final one is resolved as capital Pi in the blind audit)') for n in r['notes']]
r['notes'].append('The independent image-only reading prompted four changed boxes: local parenthesis/cancelled-factor uncertainty in the calculation, a possible pas sur previously compressed to pour, capital Pi in the Teichmüller insertion, and tau among the isolated-mark alternatives. This does not change the verified inner-conjugation identities; the only equation change is explicit uncertainty about ink already present or obscured. The complete first, second and final readings are retained in the audit table.')
r['hand'].append('Blind audit: distinguish the small main-line pi with curved right foot from the interlinear indexed capital Pi with two full legs. This is a local distinction, not a uniform capitalization rule. A very pale internal word sequence can hide a gap: the qualification after du moins retains pas sur/pour/par sur alternatives.')
write_adjudication(6,'/root/reader_a',choices,edits,report_replace={k:r[k] for k in ['changes','doubts','unlisted_decisions','inventory','notes','hand']})
